export function renderHud(el, state) { const { health, mana, gold, cooldowns } = state.player; el.innerHTML = `<div class="hud"><div class="portrait">⚔️</div><div class="bars"><meter min="0" max="100" value="${health}"></meter><meter min="0" max="100" value="${mana}"></meter></div><div class="gold">🪙 ${gold.toLocaleString()}</div><div class="skills">${skill('Dash', cooldowns.dash, '💨')}${skill('Hook', cooldowns.hook, '🪝')}${skill('Spin', cooldowns.spin, '🌀')}</div><aside class="enemy-panel"><h3>Enemy Group</h3>${state.enemies.map((enemy) => `<p class="${enemy.dead ? 'dead' : ''}">${enemy.type}<meter min="0" max="160" value="${Math.max(0, enemy.health)}"></meter></p>`).join('')}</aside></div>`; }
function skill(name, cd, icon) { return `<button class="skill">${icon}<span>${name}</span>${cd > 0 ? `<b>${cd.toFixed(1)}</b>` : ''}</button>`; }
